//! The configuration file

use std::{fs, path::PathBuf, str::FromStr};

use rustsec::{WarningKind, advisory, report};
use serde::{Deserialize, Serialize};

use crate::{
    commands::AuditCommand,
    error::{Error, ErrorKind},
};

/// `cargo audit` configuration:
///
/// An optional TOML config file located in `~/.cargo/audit.toml` or
/// `.cargo/audit.toml`.
#[derive(Clone, Debug, Default, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct AuditConfig {
    /// Advisory-related configuration
    #[serde(default)]
    pub advisories: AdvisoryConfig,

    /// Advisory Database configuration
    #[serde(default)]
    pub database: DatabaseConfig,

    /// Output configuration
    #[serde(default)]
    pub output: OutputConfig,

    /// Target-related configuration
    #[serde(default)]
    pub target: TargetConfig,

    /// Configuration for auditing for yanked crates
    #[serde(default)]
    pub yanked: YankedConfig,
}

impl AuditConfig {
    /// Load `audit.toml` (if it exists), overriding it with command-line arguments
    pub fn load(cli: &AuditCommand) -> Result<Self, Error> {
        // Check if the config file exists, and if it does not, ignore it.
        //
        // The order of precedence for which config file to use is:
        // 1. The current project's `.cargo` configuration directory.
        // 2. The current user's home directory configuration.

        let mut base = None;
        if let Ok(home) = home::cargo_home() {
            let home_config = home.join(CONFIG_FILE);
            if home_config.exists() {
                base = Some(home.join(CONFIG_FILE));
            }
        };

        let project_config_filename = PathBuf::from("./.cargo").join(CONFIG_FILE);
        if project_config_filename.exists() {
            base = Some(project_config_filename);
        }

        let mut config = match base {
            Some(path) => {
                let toml_string = fs::read_to_string(&path).map_err(|e| {
                    ErrorKind::Config.context(format!("couldn't read {}: {e}", path.display()))
                })?;
                toml::from_str(&toml_string).map_err(|e| ErrorKind::Parse.context(e))?
            }
            None => Self::default(),
        };

        config.apply(cli)?;
        Ok(config)
    }

    /// Apply overrides from CLI options
    pub fn apply(&mut self, cli: &AuditCommand) -> Result<(), Error> {
        if let Some(db) = &cli.db {
            self.database.path = Some(db.into());
        }

        for advisory_id in &cli.ignore {
            self.advisories.ignore.push(
                advisory_id
                    .parse()
                    .map_err(|e| ErrorKind::Parse.context(e))?,
            );
        }

        if let Some(warn) = cli.warn_unused_ignores {
            self.advisories.warn_unused_ignores = warn;
        }

        self.database.fetch &= !cli.no_fetch;
        self.database.stale |= cli.stale;

        if !cli.target_arch.is_empty() {
            self.target.arch = Some(FilterList::Many(cli.target_arch.clone()));
        }

        if !cli.target_os.is_empty() {
            self.target.os = Some(FilterList::Many(cli.target_os.clone()));
        }

        if let Some(url) = &cli.url {
            self.database.url = Some(url.clone())
        }

        for kind in &cli.deny {
            if *kind == DenyOption::Warnings {
                self.output.deny = DenyOption::all();
            } else {
                self.output.deny.push(*kind);
            }
        }

        self.output.quiet |= cli.quiet;
        if cli.quiet {
            self.output.show_tree = false;
        }

        // Handle output format (--json flag takes precedence for backward compatibility)
        if cli.output_json {
            self.output.format = OutputFormat::Json;
        } else if let Some(format) = cli.output_format {
            self.output.format = format;
        }

        if cli.no_yanked {
            self.yanked.enabled = false;
        }

        Ok(())
    }

    /// Get audit report settings from the configuration
    pub fn report_settings(&self) -> report::Settings {
        let mut settings = report::Settings {
            ignore: self.advisories.ignore.clone(),
            severity: self.advisories.severity_threshold,
            target_arch: self.target.arch(),
            target_os: self.target.os(),
            ..Default::default()
        };

        if let Some(informational_warnings) = &self.advisories.informational_warnings {
            settings
                .informational_warnings
                .clone_from(informational_warnings);
        } else {
            // Alert for all informational packages by default
            settings.informational_warnings = vec![
                advisory::Informational::Unmaintained,
                advisory::Informational::Unsound,
                advisory::Informational::Notice,
            ];
        }

        // Enable warnings for all informational advisories if they are marked deny.
        // Deny only works on the output if a corresponding advisory is found but only the
        // informational categories listed in informational_warnings are reported.
        // This means that if "Unsound" is missing from informational_warnings then deny unsound
        // will not do anything.
        // To fix this always add the corresponding warning category
        let mut insert_if_not_present = |warning| {
            if !settings.informational_warnings.contains(&warning) {
                settings.informational_warnings.push(warning);
            }
        };

        for deny in &self.output.deny {
            match deny {
                DenyOption::Warnings => {
                    insert_if_not_present(advisory::Informational::Notice);
                    insert_if_not_present(advisory::Informational::Unmaintained);
                    insert_if_not_present(advisory::Informational::Unsound);
                    break;
                }
                DenyOption::Unmaintained => {
                    insert_if_not_present(advisory::Informational::Unmaintained)
                }
                DenyOption::Unsound => insert_if_not_present(advisory::Informational::Unsound),
                DenyOption::Yanked => continue,
            };
        }

        settings
    }
}

/// Advisory-related configuration.
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct AdvisoryConfig {
    /// Ignore advisories for the given IDs
    #[serde(default)]
    pub ignore: Vec<advisory::Id>,

    /// Warn when ignored advisories no longer affect the audited lockfile
    /// (default: true)
    #[serde(default = "default_true")]
    pub warn_unused_ignores: bool,

    /// Warn for the given types of informational advisories
    pub informational_warnings: Option<Vec<advisory::Informational>>,

    /// CVSS Qualitative Severity Rating Scale threshold to alert at.
    ///
    /// Vulnerabilities with explicit CVSS info which have a severity below
    /// this threshold will be ignored.
    pub severity_threshold: Option<advisory::Severity>,
}

impl Default for AdvisoryConfig {
    fn default() -> Self {
        Self {
            ignore: Vec::new(),
            warn_unused_ignores: true,
            informational_warnings: None,
            severity_threshold: None,
        }
    }
}

/// Advisory Database configuration.
///
/// The advisory database is stored in a Git repository. This section of the
/// configuration stores settings related to it.
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct DatabaseConfig {
    /// Path to the local copy of advisory database's git repo (default: ~/.cargo/advisory-db)
    pub path: Option<PathBuf>,

    /// URL to the advisory database's git repo (default: <https://github.com/RustSec/advisory-db>)
    pub url: Option<String>,

    /// Perform a `git fetch` before auditing (default: true)
    #[serde(default = "default_true")]
    pub fetch: bool,

    /// Allow a stale advisory database? (i.e. one which hasn't been updated in 90 days)
    pub stale: bool,
}

impl DatabaseConfig {
    pub(crate) fn url(&self) -> &str {
        self.url
            .as_ref()
            .map(AsRef::as_ref)
            .unwrap_or(rustsec::repository::git::DEFAULT_URL)
    }

    pub(crate) fn path(&self) -> PathBuf {
        self.path
            .as_ref()
            .cloned()
            .unwrap_or_else(rustsec::repository::git::Repository::default_path)
    }

//! Core auditing functionality

use std::{
    io::{self, Read},
    path::Path,
    time::Duration,
};

use rustsec::registry::CachedIndex;
use rustsec::{Collection, binary_scanning::BinaryFormat, database::Query};
use rustsec::{Error, ErrorKind, Lockfile, Warning, WarningKind, report};

use crate::config::DatabaseConfig;
use crate::{
    config::AuditConfig,
    error::display_err_with_source,
    presenter::Presenter,
    terminal::{status_err, status_ok, status_warn},
};

// TODO: make configurable
const DEFAULT_LOCK_TIMEOUT: Duration = Duration::from_secs(5 * 60);

#[cfg(feature = "binary-scanning")]
const DEFAULT_MAX_BINARY_SIZE: u64 = 100 * 1024 * 1024; // 100MB

/// Security vulnerability auditor
pub struct Auditor {
    /// RustSec Advisory Database
    database: rustsec::Database,

    /// Crates.io registry index
    registry_index: Option<CachedIndex>,

    /// Presenter for displaying the report
    presenter: Presenter,

    /// Audit report settings
    report_settings: report::Settings,

    /// Warn about ignore entries no longer needed by the audited lockfile
    warn_unused_ignores: bool,

    /// Binary scanning configuration (max input size)
    #[cfg(feature = "binary-scanning")]
    binary_size_limit: Option<u64>,

    /// Binary scanning configuration (max auditable payload size)
    #[cfg(feature = "binary-scanning")]
    audit_data_size_limit: Option<usize>,
}

impl Auditor {
    /// Initialize the auditor
    pub fn new(config: &AuditConfig) -> Result<Self, Error> {
        let advisory_db_path = config.database.path();
        let database = if config.database.fetch {
            update_db(
                &advisory_db_path,
                &config.database,
                config.output.is_quiet(),
            )?
        } else {
            rustsec::Database::open(&advisory_db_path).map_err(|e| {
                Error::with_source(
                    ErrorKind::Repo,
                    format!("error loading advisory db: {}", advisory_db_path.display()),
                    e,
                )
            })?
        };

        if !config.output.is_quiet() {
            status_ok!(
                "Loaded",
                "{} security advisories (from {})",
                database.iter().count(),
                advisory_db_path.display()
            );
        }

        let registry_index = if config.yanked.enabled {
            if config.yanked.update_index && config.database.fetch {
                if !config.output.is_quiet() {
                    status_ok!("Updating", "crates.io index");
                }

                let user_agent = format!("cargo-audit/{}", crate::VERSION);
                let mut result = CachedIndex::fetch_as(Duration::from_secs(0), user_agent.clone());

                // If the directory is locked, print a message and wait for it to become unlocked.
                // If we don't print the message, `cargo audit` would just hang with no explanation.
                if let Err(e) = &result
                    && e.kind() == ErrorKind::LockTimeout
                {
                    status_warn!(
                        "directory {} is locked, waiting for up to {} seconds for it to become available",
                        advisory_db_path.display(),
                        DEFAULT_LOCK_TIMEOUT.as_secs()
                    );
                    result = CachedIndex::fetch_as(DEFAULT_LOCK_TIMEOUT, user_agent);
                }

                match result {
                    Ok(index) => Some(index),
                    Err(err) => {
                        if !config.output.is_quiet() {
                            status_warn!("couldn't update crates.io index: {}", err);
                        }

                        None
                    }
                }
            } else {
                let mut result = CachedIndex::open(Duration::from_secs(0));

                // If the directory is locked, print a message and wait for it to become unlocked.
                // If we don't print the message, `cargo audit` would just hang with no explanation.
                if let Err(e) = &result
                    && e.kind() == ErrorKind::LockTimeout
                {
                    status_warn!(
                        "directory {} is locked, waiting for up to {} seconds for it to become available",
                        advisory_db_path.display(),
                        DEFAULT_LOCK_TIMEOUT.as_secs()
                    );
                    result = CachedIndex::open(DEFAULT_LOCK_TIMEOUT)
                }

                match result {
                    Ok(index) => Some(index),
                    Err(err) => {
                        if !config.output.is_quiet() {
                            status_warn!("couldn't open crates.io index: {}", err);
                        }

                        None
                    }
                }
            }
        } else {
            None
        };

        Ok(Self {
            database,
            registry_index,
            presenter: Presenter::new(&config.output),
            report_settings: config.report_settings(),
            warn_unused_ignores: config.advisories.warn_unused_ignores,
            #[cfg(feature = "binary-scanning")]
            binary_size_limit: Some(DEFAULT_MAX_BINARY_SIZE),
            #[cfg(feature = "binary-scanning")]
            audit_data_size_limit: None,
        })
    }

    /// Perform an audit of a textual `Cargo.lock` file
    pub fn audit_lockfile(&mut self, lockfile_path: &Path) -> rustsec::Result<rustsec::Report> {
        let lockfile = match self.load_lockfile(lockfile_path) {
            Ok(l) => l,
            Err(e) => {
                return Err(Error::with_source(
                    ErrorKind::NotFound,
                    format!("Couldn't load {}", lockfile_path.display()),
                    e,
                ));
            }
        };

        self.presenter.before_report(lockfile_path, &lockfile);

        let report = self.audit(&lockfile, None, None);

        if self.warn_unused_ignores {
            self.warn_unused_ignores(&lockfile);
        }

        let self_advisories = self.self_advisories();

        self.presenter.print_self_report(self_advisories.as_slice());

        report
    }

    fn warn_unused_ignores(&self, lockfile: &Lockfile) {
        if self.report_settings.ignore.is_empty() {
            return;
        }

        // Query with only the collection and withdrawn filters. The severity,
        // target and informational-warning filters from `crate_scope()` are
        // left out on purpose: they only hide advisories from the report, so
        // an ignore they hide would still be wrongly called unused.
        let query = Query::new().collection(Collection::Crates).withdrawn(false);
        let affected = self.database.query_vulnerabilities(lockfile, &query);
        for id in &self.report_settings.ignore {
            if !affected.iter().any(|vuln| &vuln.advisory.id == id) {
                status_warn!("ignored advisory {} is not needed for this lockfile", id);
            }
        }
    }

    #[cfg(feature = "binary-scanning")]
    /// Perform an audit of multiple binary files
    pub fn audit_binaries<P>(&mut self, binaries: &[P]) -> MultiFileReportSummmary
    where
        P: AsRef<Path>,
    {
        let mut summary = MultiFileReportSummmary::default();
        for path in binaries {
            let result = self.audit_binary(path.as_ref());
            match result {
                Ok(report) => {
                    if self.presenter.should_exit_with_failure(&report) {
                        summary.vulnerabilities_found = true;
                    }
                }
                Err(e) => {
                    status_err!("{}", display_err_with_source(&e));
                    summary.errors_encountered = true;
                }
            }
        }

        let self_advisories = self.self_advisories();

        self.presenter.print_self_report(self_advisories.as_slice());

        if self
            .presenter
            .should_exit_with_failure_due_to_self(&self.self_advisories())
        {
            summary.errors_encountered = true;
        }
        summary
    }

    #[cfg(feature = "binary-scanning")]
    /// Configure binary-scanning limits for this `Auditor`.
    ///
    /// `max_binary_size` is in bytes. If unset, defaults to 100MB.
    ///
    /// `audit_data_size_limit` is the maximum size (in bytes) of embedded auditable payload data
    /// to parse. If unset, the default from `rustsec` applies (currently 8MB).
    pub fn set_binary_scan_limits(
        &mut self,
        max_binary_size: Option<u64>,
        audit_data_size_limit: Option<usize>,
    ) {
        self.binary_size_limit = Some(max_binary_size.unwrap_or(DEFAULT_MAX_BINARY_SIZE));
        self.audit_data_size_limit = audit_data_size_limit.or(Some(8 * 1024 * 1024));
    }

    #[cfg(feature = "binary-scanning")]
    /// Perform an audit of a binary file with dependency data embedded by `cargo auditable`
    fn audit_binary(&mut self, binary_path: &Path) -> rustsec::Result<rustsec::Report> {
        use rustsec::binary_scanning::BinaryReport::*;
        let file_contents = self.read_binary_with_limit(binary_path)?;
        let (binary_type, report) = rustsec::binary_scanning::load_deps_from_binary(
            &file_contents,
            self.audit_data_size_limit,
        )?;
        self.presenter.binary_scan_report(&report, binary_path);
        self.presenter.set_binary_contents(file_contents);
        match report {
            Complete(lockfile) | Incomplete(lockfile) => {
                self.audit(&lockfile, Some(binary_path), Some(binary_type))
            }
            None => Err(Error::new(
                ErrorKind::Parse,
                "No dependency information found! Is this a Rust executable built with cargo?",
            )),
        }
    }

    #[cfg(feature = "binary-scanning")]
    fn read_binary_with_limit(&self, binary_path: &Path) -> rustsec::Result<Vec<u8>> {
        let file = std::fs::File::open(binary_path)?;
        let limit = self.binary_size_limit.unwrap_or(DEFAULT_MAX_BINARY_SIZE);
        let mut limited = file.take(limit.saturating_add(1));
        let mut buffer = Vec::new();
        limited.read_to_end(&mut buffer)?;
        if buffer.len() as u64 > limit {
            return Err(Error::new(
                ErrorKind::BadParam,
                format!(
                    "binary {} exceeds max size limit of {} bytes",
                    binary_path.display(),
                    limit
                ),
            ));
        }
        Ok(buffer)
    }

    /// The part of the auditing process that is shared between auditing lockfiles and binary files
    fn audit(
        &mut self,
        lockfile: &Lockfile,
        path: Option<&Path>,
        #[allow(unused_variables)] // May be unused when the "binary-scanning" feature is disabled
        binary_format: Option<BinaryFormat>,
    ) -> rustsec::Result<rustsec::Report> {
        let mut report = rustsec::Report::generate(&self.database, lockfile, &self.report_settings);

        #[cfg(feature = "binary-scanning")]
        if let Some(format) = binary_format {
            use rustsec::binary_scanning::filter_report_by_binary_type;
            filter_report_by_binary_type(&format, &mut report);
        }

        // Warn for yanked crates
        let mut yanked = self.check_for_yanked_crates(lockfile);
        if !yanked.is_empty() {
            report
                .warnings
                .entry(WarningKind::Yanked)
                .or_default()
                .append(&mut yanked);

