            Ok(report) => match auditor.should_exit_with_failure(&report) {
                true => ExitCode::FAILURE,
                false => ExitCode::SUCCESS,
            },
            Err(e) => {
                status_err!("{}", display_err_with_source(&e));
                ExitCode::from(2)
            }
        })
    }
}

