    #[cfg(feature = "binary-scanning")]
    fn read_binary_with_limit(&self, binary_path: &Path) -> rustsec::Result<Vec<u8>> {
        let file = std::fs::File::open(binary_path)?;
        let limit = self.binary_size_limit.unwrap_or(DEFAULT_MAX_BINARY_SIZE);
