        match s {
            "warnings" => Ok(Self::Warnings),
            "unmaintained" => Ok(Self::Unmaintained),
            "unsound" => Ok(Self::Unsound),
            "yanked" => Ok(Self::Yanked),
            other => Err(ErrorKind::Parse.context(format!("invalid deny option: {other}"))),
        }
    }
}

