    pub fn severity(self) -> Severity {
        if self.0 < 0.1 {
            Severity::None
        } else if self.0 < 4.0 {
            Severity::Low
        } else if self.0 < 7.0 {
            Severity::Medium
        } else if self.0 < 9.0 {
            Severity::High
        } else {
            Severity::Critical
        }
    }
}

impl From<f64> for Score {
    fn from(score: f64) -> Self {
        Self(score)
    }
}

impl From<Score> for f64 {
    fn from(score: Score) -> Self {
        score.value()
    }
}

impl From<Score> for Severity {
    fn from(score: Score) -> Self {
        score.severity()
    }
}

