+        .map_err(|e| ErrorKind::Parse.context(e))?;
+
+    let advisories = document
+        .entry("advisories")
+        .or_insert(toml_edit::Item::Table(toml_edit::Table::new()));
+    let advisories = advisories.as_table_mut().ok_or_else(|| {
+        ErrorKind::Config.context("`advisories` in audit.toml must be a table")
+    })?;
+
+    let mut array = toml_edit::Array::new();
+    for id in ignores {
+        array.push(id.to_string());
+    }
+    advisories.insert("ignore", toml_edit::value(array));
+
+    fs::write(path, document.to_string()).map_err(|e| {
+        ErrorKind::Io.context(format!("couldn't write {}: {e}", path.display()))
+    })
+}
+
+fn resolve_ignore_file(path: &Path) -> PathBuf {
+    if path.is_absolute() {
+        path.to_path_buf()
+    } else {
+        PathBuf::from(".").join(path)
+    }
+}
